-- ============================================================================
-- Fix id sequences that drifted behind their tables' actual max(id).
--
-- Cause: rows were seeded with EXPLICIT ids. For `generated by default as
-- identity` columns a hand-supplied id is accepted but does NOT advance the
-- identity sequence, so the sequence keeps handing out ids that already exist
-- ("duplicate key value violates unique constraint ..._pkey").
--
-- Symptoms: adding an API key (or key + models) fails with a pkey violation.
--            key_models was already at max id 69 while its sequence was still
--            near the start; api_keys was at max id 25 while inserts got 2,3,4…
--
-- Fix: set every primary-key identity/serial sequence in `public` to
-- max(id) + 1. Safe to re-run at any time.
-- Run this in the Supabase SQL Editor.
-- ============================================================================

do $$
declare
  t record;
begin
  for t in
    select
      n.nspname as schem,
      c.relname as tbl,
      a.attname as col
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    join pg_attribute a
      on a.attrelid = c.oid and a.attnum > 0 and not a.attisdropped
    join pg_constraint con
      on con.conrelid = c.oid
     and con.contype = 'p'
     and a.attnum = any (con.conkey)
    where c.relkind = 'r'
      and n.nspname = 'public'
      and pg_get_serial_sequence(format('%I.%I', n.nspname, c.relname), a.attname) is not null
  loop
    execute format(
      'select setval(pg_get_serial_sequence(%L, %L), coalesce((select max(%I) from %I.%I), 0) + 1, false)',
      t.schem || '.' || t.tbl,
      t.col,
      t.col,
      t.schem,
      t.tbl
    );
    raise notice 'fixed sequence %.%.%', t.schem, t.tbl, t.col;
  end loop;
end $$;
